// Weekly time attack (docs/SOCIAL.md 2.9, migrations 0049, 0051, 0054; the owner, 2026-11-11: "a weekly time attack circuit
// per area", then "autogenerated in any area we have users weekly, not based on user stages ... the best loops roads in the
// area chosen at random. Possibly small loops"). An area is a 1-degree square (about 110 by 90 km). Each Monday (UTC) the
// area's circuit is a small loop over its best roads: the server can't route, so the first phone in the area that week asks,
// is handed the week's seed (`make`), builds the loop with Vetta's own router (web/time_attack.js makeLoop: a start picked at
// random from the seed, the router's best loops from there, one of the best few picked at random), and posts it. The server
// checks it (a closed loop of MIN_M to MAX_M that starts in the area) and keeps the first; every other phone gets that one.
// Nobody's name is on it. Entering copies it into your Stages and is the opt-in (ta_joins); your quickest time on it that
// week (the Log times stage runs on the phone, as for boards) goes on a board every member can see, by handle, with that
// run's Vetta Score. Leaving takes your time off and your entry. Blocks hide people both ways; a loop is reportable (kind
// `circuit`), and one a moderator takes down is built again from the next seed. Times only from runs the phone timed; an
// average speed no car on a public road could hold is refused rather than ranked.
import type { Viewer } from "./auth";
import { Env, HttpError, body, int, num, str, DATE_RE } from "./util";
import { removedSql, reportedSql } from "./reports_sql";

/** A loop: 5 to 25 km (the phone aims for LOOP_KM), closed within CLOSE_M, every point within SLACK_DEG of its area. */
export const MIN_M = 5000, MAX_M = 25000, CLOSE_M = 250, SLACK_DEG = 0.3, MAX_PTS = 6000, BOARD_SIZE = 50, KEEP_WEEKS = 8;
/** What the phone is asked to build: a small loop, 8 to 16 km. */
export const LOOP_KM = { min: 8, max: 16 };
/** Faster than this on average over a whole stage (60 m/s, 216 km/h) is not a run, it's a bad clock or a fake. */
export const MAX_AVG_MS = 60;

const first = <T>(env: Env, sql: string, ...args: unknown[]) => env.DB.prepare(sql).bind(...args).first<T>();
const all = async <T>(env: Env, sql: string, ...args: unknown[]) => (await env.DB.prepare(sql).bind(...args).all<T>()).results;
const NO_BLOCK = (a: string, b: string) => `NOT EXISTS (SELECT 1 FROM blocks k WHERE (k.blocker = ${a} AND k.blocked = ${b}) OR (k.blocker = ${b} AND k.blocked = ${a}))`;
/** The Monday (UTC) that starts this week, and the Sunday that ends it. */
const WEEK = "date('now', '-6 days', 'weekday 1')";

/** The area a point is in: the 1-degree square, south-west corner, as 'lat,lon'. */
export const cellOf = (lat: number, lon: number) => `${Math.floor(lat)},${Math.floor(lon)}`;
const qNum = (u: URL, k: string) => { const s = u.searchParams.get(k); return s === null || s.trim() === "" ? NaN : Number(s); };   // missing is 400, never (0, 0)
const cellParam = (u: URL) => cellOf(num(qNum(u, "lat"), "lat", -85, 85), num(qNum(u, "lon"), "lon", -180, 180));
const cellBody = (c: unknown) => {
  const m = /^(-?\d{1,2}),(-?\d{1,3})$/.exec(String(c ?? ""));
  if (!m || Math.abs(+m[1]) > 85 || Math.abs(+m[2]) > 180) throw new HttpError(400, "bad_cell");
  return `${+m[1]},${+m[2]}`;
};
/** The seed a phone builds this week's loop from: the same for every phone in the area, a new one after a take-down. */
export const seedOf = (week: string, cell: string, tries: number) => `${week}|${cell}|${tries}`;

const R = 6371008.8, rad = (d: number) => (d * Math.PI) / 180;
const hav = (a: number[], b: number[]) => {
  const dl = rad(b[0] - a[0]), dn = rad(b[1] - a[1]);
  const h = Math.sin(dl / 2) ** 2 + Math.cos(rad(a[0])) * Math.cos(rad(b[0])) * Math.sin(dn / 2) ** 2;
  return 2 * R * Math.asin(Math.min(1, Math.sqrt(h)));
};
/**
 * A loop the phone built, checked: [[lat, lon], ...] of MAX_PTS at most, starting in `cell` and never more than SLACK_DEG
 * outside it, back within CLOSE_M of its start, MIN_M to MAX_M long (measured here, never taken from the phone), and no
 * jump over 2 km between points (a line drawn, not roads). → { geom (rounded to 5 decimals), length_m } or a 400.
 */
export function checkLoop(raw: unknown, cell: string): { geom: [number, number][]; length_m: number } {
  if (!Array.isArray(raw) || raw.length < 10 || raw.length > MAX_PTS) throw new HttpError(400, "bad_geom");
  const pts = raw.map((p) => {
    if (!Array.isArray(p) || p.length < 2 || !Number.isFinite(p[0]) || !Number.isFinite(p[1]) || Math.abs(p[0]) > 85 || Math.abs(p[1]) > 180) throw new HttpError(400, "bad_geom");
    return [Math.round(p[0] * 1e5) / 1e5, Math.round(p[1] * 1e5) / 1e5] as [number, number];
  });
  const [la, lo] = cell.split(",").map(Number);
  if (cellOf(pts[0][0], pts[0][1]) !== cell) throw new HttpError(400, "not_in_area");
  if (pts.some(([y, x]) => y < la - SLACK_DEG || y > la + 1 + SLACK_DEG || x < lo - SLACK_DEG || x > lo + 1 + SLACK_DEG)) throw new HttpError(400, "not_in_area");
  let len = 0;
  for (let i = 1; i < pts.length; i++) { const d = hav(pts[i - 1], pts[i]); if (d > 2000) throw new HttpError(400, "bad_geom"); len += d; }
  if (hav(pts[0], pts[pts.length - 1]) > CLOSE_M) throw new HttpError(400, "not_a_loop");
  if (len < MIN_M || len > MAX_M) throw new HttpError(400, "bad_length");
  return { geom: pts, length_m: Math.round(len) };
}
/** A loop's name: the phone names it by its main road ("Dry Ridge Road loop"); plain text, 60 characters at most. */
const nameOf = (v: unknown) => {
  const s = typeof v === "string" ? v.replace(/[\u0000-\u001f\u007f<>]/g, "").replace(/\s+/g, " ").trim().slice(0, 60) : "";
  return s || "This week's loop";
};

// ---- the week's circuit ------------------------------------------------------------------------
type Circuit = { week: string; ends_on: string; cell: string; segment_id: string; name: string; length_m: number; geom: string };
type Week = { week: string; ends_on: string; today: string; circuit: Circuit | null; make: { seed: string; km: typeof LOOP_KM } | null };
/** This week's circuit for an area; none yet (or this week's taken down): `make`, the seed a phone builds one from. */
async function current(env: Env, cell: string): Promise<Week> {
  const w = (await first<{ week: string; ends_on: string; today: string }>(env,
    `SELECT ${WEEK} AS week, date(${WEEK}, '+6 days') AS ends_on, date('now') AS today`))!;
  const row = await first<{ segment_id: string; name: string | null; length_m: number | null; geom: string | null; tries: number; removed: number }>(env,
    "SELECT segment_id, name, length_m, geom, tries, removed FROM ta_weeks WHERE week = ? AND cell = ?", w.week, cell);
  const shown = row && row.geom && !row.removed
    && !(await first(env, `SELECT 1 WHERE ${reportedSql("circuit", "?1")}`, row.segment_id));
  const circuit = shown ? { week: w.week, ends_on: w.ends_on, cell, segment_id: row!.segment_id, name: row!.name || "This week's loop", length_m: row!.length_m!, geom: row!.geom! } : null;
  // a row with no loop on it is a member's stage picked before 0054 (or one taken down): built again, from the next seed
  const make = circuit || (row && row.geom && !row.removed) ? null : { seed: seedOf(w.week, cell, row ? row.tries + (row.removed ? 0 : 1) : 0), km: LOOP_KM };
  return { ...w, circuit, make };
}

/**
 * POST /api/timeattack/circuit {cell, seed, name, geom}: the loop a phone built from this week's seed. The first that checks
 * out is the area's for the week (a race answers with the one kept); a seed that isn't this week's is a 409.
 */
export async function makeCircuit(env: Env, v: Viewer, req: Request) {
  const b = await body<{ cell?: unknown; seed?: unknown; name?: unknown; geom?: unknown }>(req);
  const cell = cellBody(b.cell);
  const now = await current(env, cell);
  if (now.circuit) return { circuit: now.circuit, kept: false };
  if (!now.make || b.seed !== now.make.seed) throw new HttpError(409, "stale_seed");
  const loop = checkLoop(b.geom, cell);
  const id = "ta-" + crypto.randomUUID(), tries = Number(String(now.make.seed).split("|")[2]) || 0;
  const geom = JSON.stringify(loop.geom), name = nameOf(b.name);
  // the first loop for the week, or in place of a member's stage (geom null) or one taken down; the week's board and
  // entries for the old one go with it (a new circuit starts empty)
  const res = await env.DB.prepare(`INSERT INTO ta_weeks (week, cell, segment_id, name, length_m, geom, tries, removed) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, 0)
     ON CONFLICT (week, cell) DO UPDATE SET segment_id = ?3, name = ?4, length_m = ?5, geom = ?6, tries = ?7, removed = 0
     WHERE ta_weeks.geom IS NULL OR ta_weeks.removed = 1`).bind(now.week, cell, id, name, loop.length_m, geom, tries).run();
  if (res.meta.changes) await env.DB.batch([
    env.DB.prepare("DELETE FROM ta_entries WHERE week = ? AND cell = ?").bind(now.week, cell),
    env.DB.prepare("DELETE FROM ta_joins WHERE week = ? AND cell = ?").bind(now.week, cell),
  ]);
  const after = await current(env, cell);
  return { circuit: after.circuit, kept: !!res.meta.changes };
}

/** GET /api/timeattack?lat&lon: the area's circuit this week (or the seed to build it), its board (quickest first), your place, and last week's podium. */
export async function timeAttack(env: Env, v: Viewer, url: URL) {
  const cell = cellParam(url);
  const { week, ends_on, today, circuit, make } = await current(env, cell);
  const rows = circuit ? await all<{ user_id: string; handle: string | null; time_s: number; driver_score: number | null; driven_on: string }>(env,
    `SELECT e.user_id, u.handle, e.time_s, e.driver_score, e.driven_on FROM ta_entries e JOIN users u ON u.id = e.user_id
      WHERE e.week = ?1 AND e.cell = ?2 AND (e.user_id = ?3 OR ${NO_BLOCK("e.user_id", "?3")})
      ORDER BY e.time_s, e.updated_at, u.handle LIMIT 500`, week, cell, v.id) : [];
  const best = rows.length ? rows[0].time_s : null;
  const placed = rows.map((r, i) => ({ place: i && rows[i - 1].time_s === r.time_s ? -1 : i + 1, r }))
    .map((x, i, a) => ({ ...x, place: x.place > 0 ? x.place : a.slice(0, i).reverse().find((y) => y.place > 0)!.place }));
  const out = (x: typeof placed[number]) => ({ place: x.place, handle: x.r.handle || "?", time_s: x.r.time_s, gap_s: best == null ? null : x.r.time_s - best,
    score: x.r.driver_score, driven_on: x.r.driven_on, mine: x.r.user_id === v.id });
  const me = placed.find((x) => x.r.user_id === v.id);
  const entered = circuit ? !!(await first(env, "SELECT 1 FROM ta_joins WHERE week = ? AND cell = ? AND user_id = ?", week, cell, v.id)) : false;
  const last = await first<{ name: string | null; removed: number }>(env,
    "SELECT name, removed FROM ta_weeks WHERE week = date(?1, '-7 days') AND cell = ?2 AND geom IS NOT NULL", week, cell);
  const podium = last && !last.removed ? await all<{ handle: string | null; time_s: number }>(env,
    `SELECT u.handle, e.time_s FROM ta_entries e JOIN users u ON u.id = e.user_id WHERE e.week = date(?1, '-7 days') AND e.cell = ?2
      AND (e.user_id = ?3 OR ${NO_BLOCK("e.user_id", "?3")}) ORDER BY e.time_s, e.updated_at, u.handle LIMIT 3`, week, cell, v.id) : [];
  return { week, ends_on, today, cell, circuit, make, entered, entrants: rows.length,
    board: placed.slice(0, BOARD_SIZE).map(out), you: me ? out(me) : null,
    last: last && !last.removed ? { name: last.name || "Last week's loop", podium: podium.map((p) => ({ handle: p.handle || "?", time_s: p.time_s })) } : null };
}

/** POST /api/timeattack/enter {cell}: the week's loop goes into your Stages (a linked copy, as when a friend shares a stage). */
export async function enter(env: Env, v: Viewer, req: Request) {
  if (!v.handle) throw new HttpError(409, "handle_required");
  const { circuit } = await current(env, cellBody((await body<{ cell?: unknown }>(req)).cell));
  if (!circuit) throw new HttpError(404, "no_circuit");
  // entering is the opt-in: only a week you entered puts your times on the board (migration 0051)
  await env.DB.prepare("INSERT OR IGNORE INTO ta_joins (week, cell, user_id) VALUES (?, ?, ?)").bind(circuit.week, circuit.cell, v.id).run();
  const have = await first<{ id: string }>(env, "SELECT id FROM segments WHERE owner = ?1 AND origin_id = ?2", v.id, circuit.segment_id);
  if (have) return { segment_id: have.id, added: false };
  const g = JSON.parse(circuit.geom) as [number, number][], [a, z] = [g[0], g[g.length - 1]];
  const id = crypto.randomUUID();
  await env.DB.prepare("INSERT INTO segments (id, owner, name, length_m, geom, start_lat, start_lon, end_lat, end_lon, origin_id) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)")
    .bind(id, v.id, circuit.name, circuit.length_m, circuit.geom, a[0], a[1], z[0], z[1], circuit.segment_id).run();
  return { segment_id: id, added: true };
}

/** GET /api/timeattack/circuits: this week's circuits you entered (their stage ids), so the phone sends times only for those. */
export async function circuitsNow(env: Env, v: Viewer) {
  const w = (await first<{ week: string; ends_on: string }>(env, `SELECT ${WEEK} AS week, date(${WEEK}, '+6 days') AS ends_on`))!;
  return { ...w, circuits: await all<{ segment_id: string; cell: string }>(env,
    "SELECT w.segment_id, w.cell FROM ta_weeks w JOIN ta_joins j ON j.week = w.week AND j.cell = w.cell AND j.user_id = ? WHERE w.week = ? AND w.geom IS NOT NULL AND w.removed = 0", v.id, w.week) };
}

/**
 * POST /api/timeattack/runs {runs: [{segment_id, time_s, driver_score?, driven_on}]}: your timed runs on stages you have.
 * A run counts when its stage is a circuit this week you entered and it was driven this week; your quickest stays. A run no
 * road car could set is skipped (one bad clock never holds back the others). → { accepted, refused }.
 */
export async function runs(env: Env, v: Viewer, req: Request) {
  if (!v.handle) throw new HttpError(409, "handle_required");
  const b = await body<{ runs?: unknown }>(req);
  if (!Array.isArray(b.runs) || b.runs.length > 20) throw new HttpError(400, "bad_runs");
  let accepted = 0, refused = 0;
  for (const raw of b.runs as Record<string, unknown>[]) {
    const segId = str(raw && raw.segment_id, "segment_id", 1, 64), time = int(raw.time_s, "time_s", 10, 36000);
    const score = raw.driver_score == null ? null : int(raw.driver_score, "driver_score", 0, 1000);
    const day = str(raw.driven_on, "driven_on", 10, 10);
    if (!DATE_RE.test(day)) throw new HttpError(400, "bad_driven_on");
    const c = await first<{ cell: string; week: string; length_m: number }>(env,
      `SELECT w.cell, w.week, s.length_m FROM segments s JOIN ta_weeks w ON w.segment_id = s.origin_id AND w.week = ${WEEK} AND w.geom IS NOT NULL AND w.removed = 0
        JOIN ta_joins j ON j.week = w.week AND j.cell = w.cell AND j.user_id = ?2
        WHERE s.id = ?1 AND s.owner = ?2 AND ?3 BETWEEN w.week AND date(w.week, '+6 days') AND ?3 <= date('now', '+1 day')`, segId, v.id, day);
    if (!c) continue;
    if (c.length_m / time > MAX_AVG_MS) { refused++; continue; }
    await env.DB.prepare(`INSERT INTO ta_entries (week, cell, user_id, time_s, driver_score, driven_on) VALUES (?1, ?2, ?3, ?4, ?5, ?6)
       ON CONFLICT (week, cell, user_id) DO UPDATE SET time_s = ?4, driver_score = ?5, driven_on = ?6, updated_at = datetime('now') WHERE ?4 < ta_entries.time_s`)
      .bind(c.week, c.cell, v.id, time, score, day).run();
    accepted++;
  }
  return { accepted, refused };
}

/** DELETE /api/timeattack/entry?lat&lon: your time off this week's board for that area, and out of the week (so the next sync
 * doesn't put it back). Enter again to come back. */
export async function leave(env: Env, v: Viewer, url: URL) {
  const cell = cellParam(url);
  await env.DB.batch([
    env.DB.prepare(`DELETE FROM ta_entries WHERE user_id = ? AND cell = ? AND week = ${WEEK}`).bind(v.id, cell),
    env.DB.prepare(`DELETE FROM ta_joins WHERE user_id = ? AND cell = ? AND week = ${WEEK}`).bind(v.id, cell),
  ]);
}

export const TA_SWEEP = {
  ta_entries: `DELETE FROM ta_entries WHERE week < date('now', '-${KEEP_WEEKS * 7} days')`,
  ta_weeks: `DELETE FROM ta_weeks WHERE week < date('now', '-${KEEP_WEEKS * 7} days')`,
  ta_joins: `DELETE FROM ta_joins WHERE week < date('now', '-${KEEP_WEEKS * 7} days')`,
};
